{
  "id": "feature",
  "label": "Feature",
  "description": "Implement a planned behavior change with explicit acceptance criteria and verification.",
  "when_to_use": "Use when adding or changing user-visible behavior from an agreed request or plan.",
  "steps": [
    {
      "key": "intake",
      "label": "Confirm acceptance criteria",
      "phase": "setup",
      "guidance": "Restate the desired behavior, constraints, and how completion will be verified."
    },
    {
      "key": "test_design",
      "label": "Design verification",
      "phase": "red",
      "guidance": "Decide which tests, examples, or checks will prove the behavior before implementation."
    },
    {
      "key": "implement",
      "label": "Implement the slice",
      "phase": "green",
      "guidance": "Build the smallest coherent slice that satisfies the agreed criteria."
    },
    {
      "key": "refine",
      "label": "Refine safely",
      "phase": "refactor",
      "guidance": "Review the implemented slice against the acceptance criteria and existing invariants, including scope, compatibility, and preservation. Use an available diff or a before-and-after content comparison. If refinement is warranted, keep it small and rerun the affected verification after changes. If no refinement is warranted, state why; do not change working code merely to satisfy this step. Record the review and verification results before completing it."
    },
    {
      "key": "validate",
      "label": "Validate",
      "phase": "verify",
      "guidance": "Run targeted and relevant broader checks; compare results to acceptance criteria."
    },
    {
      "key": "handoff",
      "label": "Handoff",
      "phase": "handoff",
      "guidance": "Summarize behavior delivered, validation, and follow-up work."
    }
  ],
  "guards": []
}

